# frozen_string_literal: true

require "base64"
require "json"
require "zlib"

# Casting time, range and duration parsed from the spell entries in the PHB 2014.
# Components are intentionally omitted from product logic and interface.
module PlayerHandbook2014SpellMetadata
  DATA = ""

  def self.for(name)
    entries[normalized(name)]
  end

  def self.entries
    @entries ||= JSON.parse(Zlib::Inflate.inflate(Base64.decode64(DATA)))
  end

  def self.normalized(value)
    value.to_s.unicode_normalize(:nfd).gsub(/\p{Mn}/, "").downcase
  end
end
